def is_field(text):
    """True if ``text`` is one field as the parser reads it: non-empty, no space or tab."""
    return bool(text) and not _SEPARATOR_RE.search(text)


def is_category(text):
    """True if ``text`` is one word: a field with no whitespace and no control character.

    Whitespace is anything ``str.isspace()`` knows (form feed, U+00A0, U+2028, ...);
    control characters are the Unicode categories Cc and Cf (zero-width space, BOM, ...).
    """
    return is_field(text) and not any(
        ch.isspace() or unicodedata.category(ch) in ("Cc", "Cf", "Zl", "Zp") for ch in text
    )


def parse_date(text):
    """Parse a strict ``YYYY-MM-DD`` string into a date; raise ValueError if invalid."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %s (expected YYYY-MM-DD)" % quote(text))
    year, month, day = int(text[:4]), int(text[5:7]), int(text[8:10])
    if not 1 <= month <= 12:
        raise ValueError("invalid date %s (no such month)" % quote(text))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError("invalid date %s (no such day)" % quote(text)) from None


def parse_amount(text):
    """Parse an amount with at most two decimals into a Decimal."""
