class DateMessageTests(unittest.TestCase):
    def test_parse_date_names_what_is_wrong(self):
        from pennywise.ledger import parse_date

        cases = {
            "2024-13-01": "invalid date '2024-13-01' (no such month)",
            "2024-00-10": "invalid date '2024-00-10' (no such month)",
            "2024-02-30": "invalid date '2024-02-30' (no such day)",
            "2023-02-29": "invalid date '2023-02-29' (no such day)",
            "2024-04-31": "invalid date '2024-04-31' (no such day)",
            "2024-01-00": "invalid date '2024-01-00' (no such day)",
        }
        for text, message in cases.items():
            with self.assertRaises(ValueError, msg=text) as ctx:
                parse_date(text)
            self.assertEqual(str(ctx.exception), message)

    def test_parse_date_valid_leap_day(self):
        from pennywise.ledger import parse_date

        self.assertEqual(parse_date("2024-02-29"), datetime.date(2024, 2, 29))

    def test_ledger_line_reports_no_such_month(self):
        for text in ("2024-13-01", "2024-00-10"):
            with self.assertRaises(ParseError) as ctx:
                parse("2024-03-01 a 1\n%s a 1\n" % text)
            self.assertEqual(ctx.exception.line, 2)
            self.assertIn("invalid date '%s' (no such month)" % text, str(ctx.exception))


class LongFieldMessageTests(unittest.TestCase):
    LONG = 5000000

    def test_long_bad_line_message_is_short_and_names_line(self):
        with self.assertRaises(ParseError) as ctx:
            parse("x" * self.LONG + " bad")
        self.assertLess(len(str(ctx.exception)), 200)
